Audit this TodoList for React-specific performance issues. Users say it gets sluggish with 100+ items. I want a review, not a direct patch.

function TodoList({ todos, onToggle, onDelete }) {
  const [filter, setFilter] = useState('all')

  const filteredTodos = todos.filter(todo => {
    if (filter === 'active') return !todo.completed
    if (filter === 'completed') return todo.completed
    return true
  })

  return (
    <div>
      <div>
        <button onClick={() => setFilter('all')}>All</button>
        <button onClick={() => setFilter('active')}>Active</button>
        <button onClick={() => setFilter('completed')}>Completed</button>
      </div>
      <ul style={{ height: '600px', overflow: 'auto' }}>
        {filteredTodos.map(todo => (
          <li key={todo.id}>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => onToggle(todo.id)}
            />
            <span>{todo.text}</span>
            <button onClick={() => onDelete(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  )
}

My chat callback always uses stale state. New WebSocket messages append using old values and unreadCount increments from stale state too. What is the React fix?

function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([])
  const [unreadCount, setUnreadCount] = useState(0)

  const handleNewMessage = useCallback((msg) => {
    setMessages([...messages, msg])
    if (!document.hasFocus()) {
      setUnreadCount(unreadCount + 1)
    }
  }, [roomId])

  useEffect(() => {
    const ws = new WebSocket(`/ws/${roomId}`)
    ws.onmessage = (e) => handleNewMessage(JSON.parse(e.data))
    return () => ws.close()
  }, [roomId, handleNewMessage])

  return <div />
}

This hook reconnects the WebSocket constantly. The effect depends on handleMessage because the linter told me so, but now it disconnects and reconnects on almost every render. How should this work in React 19.2?

function useRealtimeData(userId) {
  const [data, setData] = useState(null)

  const handleMessage = (msg) => {
    setData(msg.data)
    console.log('Received update for user', userId)
  }

  useEffect(() => {
    const ws = new WebSocket('/api/realtime')
    ws.onmessage = handleMessage
    console.log('Connected')

    return () => {
      ws.close()
      console.log('Disconnected')
    }
  }, [handleMessage])

  return data
}

